public void load(CompoundTag p_22114_) {
      this.baseValue = p_22114_.getDouble("Base");
      if (p_22114_.contains("Modifiers", 9)) {
         ListTag listtag = p_22114_.getList("Modifiers", 10);

         for(int i = 0; i < listtag.size(); ++i) {
            AttributeModifier attributemodifier = AttributeModifier.load(listtag.getCompound(i));
            if (attributemodifier != null) {
               this.modifierById.put(attributemodifier.getId(), attributemodifier);
               this.getModifiers(attributemodifier.getOperation()).add(attributemodifier);
               this.permanentModifiers.add(attributemodifier);
            }
         }
      }

      this.setDirty();
   }

public void readAdditionalSaveData(CompoundTag p_21096_) {
      this.setAbsorptionAmount(p_21096_.getFloat("AbsorptionAmount"));
      if (p_21096_.contains("Attributes", 9) && this.level() != null && !this.level().isClientSide) {
         this.getAttributes().load(p_21096_.getList("Attributes", 10));
      }

      if (p_21096_.contains("ActiveEffects", 9)) {
         ListTag listtag = p_21096_.getList("ActiveEffects", 10);

         for(int i = 0; i < listtag.size(); ++i) {
            CompoundTag compoundtag = listtag.getCompound(i);
            MobEffectInstance mobeffectinstance = MobEffectInstance.load(compoundtag);
            if (mobeffectinstance != null) {
               this.activeEffects.put(mobeffectinstance.getEffect(), mobeffectinstance);
            }
         }
      }

      if (p_21096_.contains("Health", 99)) {
         this.setHealth(p_21096_.getFloat("Health"));
      }

      this.hurtTime = p_21096_.getShort("HurtTime");
      this.deathTime = p_21096_.getShort("DeathTime");
      this.lastHurtByMobTimestamp = p_21096_.getInt("HurtByTimestamp");
      if (p_21096_.contains("Team", 8)) {
         String s = p_21096_.getString("Team");
         PlayerTeam playerteam = this.level().getScoreboard().getPlayerTeam(s);
         boolean flag = playerteam != null && this.level().getScoreboard().addPlayerToTeam(this.getStringUUID(), playerteam);
         if (!flag) {
            LOGGER.warn("Unable to add mob to team \"{}\" (that team probably doesn't exist)", (Object)s);
         }
      }

      if (p_21096_.getBoolean("FallFlying")) {
         this.setSharedFlag(7, true);
      }

      if (p_21096_.contains("SleepingX", 99) && p_21096_.contains("SleepingY", 99) && p_21096_.contains("SleepingZ", 99)) {
         BlockPos blockpos = new BlockPos(p_21096_.getInt("SleepingX"), p_21096_.getInt("SleepingY"), p_21096_.getInt("SleepingZ"));
         this.setSleepingPos(blockpos);
         this.entityData.set(DATA_POSE, Pose.SLEEPING);
         if (!this.firstTick) {
            this.setPosToBed(blockpos);
         }
      }

      if (p_21096_.contains("Brain", 10)) {
         var dyn = new Dynamic<>(NbtOps.INSTANCE, p_21096_.get("Brain"));
         this.brain = net.minecraftforge.common.ForgeHooks.onLivingMakeBrain(this, this.makeBrain(dyn), dyn);
      }

   }

public Dynamic<?> fixTag(Dynamic<?> p_16412_) {
      return p_16412_.update("Brain", this::updateBrain);
   }

@Override
    public void load(CompoundTag compound) {
        super.load(compound);

        if (compound.contains(activityKey)) {
            activity = compound.getInt(activityKey);
        }

        if (compound.contains(stepKey)) {
            step = compound.getInt(stepKey);
        }

        if (compound.contains(luckKey)) {
            luck = compound.getInt(luckKey);
        }
    }

@Override
            public MapType convert(final MapType data, final long sourceVersion, final long toVersion) {
                final MapType brain = data.getMap("Brain");
                if (brain == null) {
                    return null;
                }

                final MapType memories = brain.getMap("memories");
                if (memories == null) {
                    return null;
                }

                final TypeUtil<?> typeUtil = memories.getTypeUtil();

                for (final String key : memories.keys()) {
                    final Object value = memories.getGeneric(key);

                    final MapType wrapped = typeUtil.createEmptyMap();
                    wrapped.setGeneric("value", value);

                    memories.setMap(key, wrapped);
                }

                return null;
            }

@NotNull
    public static FluidVeinWorldEntry readFromNBT(@NotNull CompoundTag tag) {
        String veinId;
        MemoizedSupplier<BedrockFluidDefinition> vein;

        if (tag.contains("vein")) {
            veinId = tag.getString("vein");
            vein = GTMemoizer.memoize(() -> {
                ResourceLocation key = ResourceLocation.parse(veinId);
                return GTRegistries.BEDROCK_FLUID_DEFINITIONS.get(key);
            });
        } else {
            veinId = null;
            vein = GTMemoizer.memoize(() -> null);
        }

        FluidVeinWorldEntry info = new FluidVeinWorldEntry(vein);
        info.veinId = veinId;
        info.fluidYield = tag.getInt("fluidYield");
        info.operationsRemaining = tag.getInt("operationsRemaining");
        return info;
    }

@NotNull
    public static OreVeinWorldEntry readFromNBT(@NotNull CompoundTag tag) {
        OreVeinWorldEntry info = new OreVeinWorldEntry();
        info.oreYield = tag.getInt("oreYield");
        info.operationsRemaining = tag.getInt("operationsRemaining");

        if (tag.contains("vein")) {
            ResourceLocation id = ResourceLocation.parse(tag.getString("vein"));
            if (GTRegistries.BEDROCK_ORE_DEFINITIONS.containsKey(id)) {
                info.definition = GTRegistries.BEDROCK_ORE_DEFINITIONS.get(id);
            }
        }
        return info;
    }
